import{_ as a,a0 as r,w as l,s as d,I as t,x as n,a1 as i,A as p,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡 | LCTT x X-CMD","titleTemplate":false,"description":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x","title":"在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡","tag":"201505","desc":""},"relativePath":"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x.md","filePath":"[post].md"}'),s={name:"201505/How to Manage Network using nmcli Tool in RedHat CentOS 7.x.md"};function c(u,e,g,C,x,N){const o=r("Link");return l(),d("div",null,[e[17]||(e[17]=t("h1",{id:"在-redhat-centos-7-x-中使用-nmcli-命令管理網絡",tabindex:"-1"},[n("在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡 "),t("a",{class:"header-anchor",href:"#在-redhat-centos-7-x-中使用-nmcli-命令管理網絡","aria-label":"Permalink to “在 RedHat/CentOS 7.x 中使用 nmcli 命令管理網絡”"},"​")],-1)),t("p",null,[i(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/7.0_Release_Notes/"},{default:p(()=>[...e[0]||(e[0]=[t("strong",null,"Red Hat Enterprise Linux 7",-1),n(" 與 ",-1),t("strong",null,"CentOS 7",-1)])]),_:1}),e[1]||(e[1]=n(" 中默認的網絡服務由 ",-1)),e[2]||(e[2]=t("strong",null,"NetworkManager",-1)),e[3]||(e[3]=n(" 提供，這是動態控制及配置網絡的守護進程，它用於保持當前網絡設備及連接處於工作狀態，同時也支持傳統的 ifcfg 類型的配置文件。",-1))]),e[18]||(e[18]=m(`<p>NetworkManager 可以用於以下類型的連接：Ethernet，VLANS，Bridges，Bonds，Teams，Wi-Fi，mobile boradband（如移動3G）以及 IP-over-InfiniBand。針對與這些網絡類型，NetworkManager 可以配置他們的網絡別名，IP 地址，靜態路由，DNS，VPN連接以及很多其它的特殊參數。</p><p>可以用命令列工具 nmcli 來控制 NetworkManager。</p><p>###nmcli 用法###</p><pre><code># nmcli [ OPTIONS ] OBJECT { COMMAND | help }
</code></pre><p>我們可以通過 TAB 鍵補全命令，當你忘記這個命令的語法時只需要按下 TAB 就可以看到選項列表。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-tab.jpg" alt="nmcli tab"></p><p>使用 nmcli 的一些例子：</p><pre><code># nmcli general status
</code></pre><p>這條命令將 NetworkManager 的所有狀態都打印出來。</p><pre><code># nmcli connection show
</code></pre><p>顯示所有連接。</p><pre><code># nmcli connection show -a
</code></pre><p>僅顯示當前活動的連接。</p><pre><code># nmcli device status
</code></pre><p>列出 NetworkManager 識別出的設備列表及他們的狀態。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-gneral.jpg" alt="nmcli general"></p><h3 id="啓動-停止-網絡接口" tabindex="-1">啓動/停止 網絡接口### <a class="header-anchor" href="#啓動-停止-網絡接口" aria-label="Permalink to “啓動/停止 網絡接口###”">​</a></h3><p>使用 nmcli 工具啓動或停止網絡接口，與 ifconfig 的 up/down 是一樣的。</p><p>使用下列命令停止某個接口：</p><pre><code># nmcli device disconnect eno16777736
</code></pre><p>下列命令用來啓動接口：</p><pre><code># nmcli device connect eno16777736
</code></pre><p>###添加靜態IP的以太網連接</p><p>以下命令可以添加一個靜態IP地址的以太網連接：</p><pre><code># nmcli connection add type ethernet con-name NAME_OF_CONNECTION ifname interface-name ip4 IP_ADDRESS gw4 GW_ADDRESS
</code></pre><p>根據你需要的配置更改 NAME_OF_CONNECTION,IP_ADDRESS, GW_ADDRESS參數（如果不需要網關的話可以省略最後一部分）。</p><pre><code># nmcli connection add type ethernet con-name NEW ifname eno16777736 ip4 192.168.1.141 gw4 192.168.1.1
</code></pre><p>使用下列命令設置DNS服務器：</p><pre><code># nmcli connection modify NEW ipv4.dns &quot;8.8.8.8 8.8.4.4&quot;
</code></pre><p>下列命令啓動新的 Ethernet 連接：</p><pre><code># nmcli connection up NEW ifname eno16777736
</code></pre><p>查看新連接的配置信息：</p><pre><code># nmcli -p connection show NEW
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-add-static.jpg" alt="nmcli add static"></p><p>###增加一個使用 DHCP 的新連接</p><p>增加新的連接，使用DHCP自動分配IP地址，網關，DNS等，你要做的就是將命令列後 ip/gw 地址部分去掉就行了，DHCP會自動分配這些參數。</p><p>例，在 eno 16777736 設備上配置一個 名為 NEW_DHCP 的 DHCP 連接</p><pre><code># nmcli connection add type ethernet con-name NEW_DHCP ifname eno16777736
</code></pre><hr>`,39)),t("p",null,[e[5]||(e[5]=n("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/"},{default:p(()=>[...e[4]||(e[4]=[n("http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=n("作者：",-1)),i(o,{href:"http://linoxide.com/author/adriand/"},{default:p(()=>[...e[6]||(e[6]=[n("Adrian Dinu",-1)])]),_:1}),e[10]||(e[10]=n(" 譯者：",-1)),i(o,{href:"https://github.com/SPccman"},{default:p(()=>[...e[7]||(e[7]=[n("SPccman",-1)])]),_:1}),e[11]||(e[11]=n(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[8]||(e[8]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=n("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[12]||(e[12]=[n("LCTT",-1)])]),_:1}),e[15]||(e[15]=n(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:p(()=>[...e[13]||(e[13]=[n("Linux中國",-1)])]),_:1}),e[16]||(e[16]=n(" 榮譽推出",-1))])])}const w=a(s,[["render",c]]);export{S as __pageData,w as default};
